// Settings come from n8n Variables; self-hosted community installs without
// Variables fall back to environment variables of the same name.
function setting(name) {
  try { return $vars?.[name] || $env[name]; } catch (error) { return undefined; }
}
function required(name) {
  const value = setting(name);
  if (!value) throw new Error(`${name} is not set (n8n Variable or environment variable)`);
  return value;
}

// Summarize the failure without copying any payload data into the alert.
const { execution = {}, workflow = {} } = $input.first().json;
const error = execution.error || {};
const lines = [
  `Workflow: ${workflow.name || 'unknown'}`,
  `Failed node: ${execution.lastNodeExecuted || error.node?.name || 'unknown'}`,
  `Error: ${error.message || 'unknown error'}`,
  `Execution: ${execution.url || execution.id || 'n/a'}`,
  `Mode: ${execution.mode || 'n/a'}`,
];
return [{
  json: {
    from: required('RESEND_FROM'),
    to: required('OPS_ALERT_EMAIL'),
    subject: `[LendLoop] ${workflow.name || 'Workflow'} failed`,
    text: lines.join('\n'),
  },
}];
